-- ============================================================
-- 環保餐廳完整資料匯入腳本
-- 資料庫: dashboard
-- ============================================================

CREATE EXTENSION IF NOT EXISTS postgis;

CREATE TABLE IF NOT EXISTS public.eco_restaurant_stats (
    district character varying(50),
    count integer,
    city character varying(50)
);

CREATE TABLE IF NOT EXISTS public.eco_restaurant_stores (
    restid character varying(50),
    name character varying(200),
    address character varying(300),
    phone character varying(50),
    city character varying(50),
    district character varying(50),
    lng double precision,
    lat double precision,
    wkb_geometry public.geometry(Point,4326)
);

TRUNCATE public.eco_restaurant_stats;
TRUNCATE public.eco_restaurant_stores;


